INSERT INTO public.contracts(contract_no,party_id,booking_id,start_date,end_date,status,legacy_contract_id,needs_review,reason,created_by,created_at) SELECT 'LEGACY-'||uc.id::text,coalesce(ta.party_id,b.party_id),uc.booking_id,uc.starts_on,uc.ends_on,'draft',uc.id,true,'عقد تاريخي للمراجعة؛ لا تُستنتج أجرة أو ضريبة أو خطة ولا تُنشأ التزامات تاريخية',uc.created_by,uc.created_at FROM public.unit_contracts uc LEFT JOIN public.tenant_accounts ta ON ta.id=uc.tenant_account_id LEFT JOIN public.bookings b ON b.id=uc.booking_id WHERE NOT EXISTS(SELECT 1 FROM public.contracts c WHERE c.legacy_contract_id=uc.id);
INSERT INTO public.contract_units(contract_id,unit_id) SELECT c.id,uc.unit_id FROM public.contracts c JOIN public.unit_contracts uc ON uc.id=c.legacy_contract_id ON CONFLICT(contract_id,unit_id) DO NOTHING;
INSERT INTO public.audit_log(actor_role,action,entity_table,entity_id,after_data,context) SELECT 'system','LEGACY_CONTRACT_LINKED','contracts',c.id::text,to_jsonb(c),jsonb_build_object('reason','حفظ عقد تاريخي للمراجعة دون توليد أقساط أو تغيير التأجير') FROM public.contracts c WHERE c.legacy_contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.audit_log a WHERE a.action='LEGACY_CONTRACT_LINKED' AND a.entity_id=c.id::text);
